INSERT INTO `freeform_submissions_reservation_1` VALUES (7401,'Andi','Werner','schmuckmacher@me.com','0786672072','5274','100,00 CHF','https://www.derschmuckmacher.ch/schmuck/5274','Test\r\n','Silberring'),(7512,'Jasmin','Hachwi','jasmin.hachwi@gmail.com','0765202210','4531','50,00 CHF','https://www.derschmuckmacher.ch/schmuck/4531','Ich habe diesen ring gesehen und will ihn meiner mama schenken ist die grösse anpasbar ? ','Bernsteinring'),(7650,'Alexander','Jost','a.jost@gmx.ch','0793174091','7644','110,00 CHF','https://www.derschmuckmacher.ch/schmuck/7644','Ist für meine Frau. Ich weiss aktuell den richtigen Durchmesser noch nicht. Gibt es den Ring in wählbaren Grössen?','Silberring'),(7727,'Rea','Zimmerli','rea.zimmerli@gmx.ch','0764532529','7724','150,00 CHF','https://www.derschmuckmacher.ch/schmuck/7724','','Labradoritarmreif'),(7758,'Andi','Werner','schmuckmacher@me.com','0786672072','7520','130,00 CHF','https://www.derschmuckmacher.ch/schmuck/7520','','Rubinring'),(7821,'Andi','W','schmuckmacher@me.com','0786672072','','','','',''),(8408,'Emina','Demirovic ','emina_94@msn.com','0041764271249','','','','',''),(8409,'Emina','Demirovic ','emina_94@msn.com','0041764271249','','','','',''),(8461,'Sandra','Buri','sanburi@gmx.ch','0792776243','','','','Guten Abend\r\nIch intressiere mich sehr für diesen Ring mit Goldeinlage, finde aber die mit Holzabbild ebenfalls toll. Kann man die Ringe besichtigen und anprobieren? Merci für Ihre Antwort.\r\nLiebe Grüsse Sandra Buri','');
